?><!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>لوحة الإدارة</title><link rel="stylesheet" href="style.css"><style>.admin{width:95%;max-width:1200px;margin:40px auto}.admin-header{background:#176b55;color:#fff;padding:25px;border-radius:15px;margin-bottom:25px}.stats{display:flex;gap:20px;margin-bottom:25px}.stat-box{background:#fff;padding:25px;border-radius:12px;box-shadow:0 5px 20px #0000000f}.table-container{background:#fff;padding:20px;border-radius:15px;overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:13px;border-bottom:1px solid #eee;text-align:right;white-space:nowrap}th{background:#f4f8f6}.delete{background:#d62828;color:#fff;padding:7px 12px;border-radius:6px}</style></head><body><div class="admin"><div class="admin-header"><h1>لوحة تحكم المنظمة</h1><p>مرحباً مدير النظام</p><a href="logout.php" class="btn btn-light">تسجيل الخروج</a></div><div class="stats"><div class="stat-box"><strong><?=$total?></strong><br>إجمالي الأعضاء</div></div><div class="table-container"><h2>الأعضاء المسجلون</h2><br><table><thead><tr><th>#</th><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>الولاية</th><th>المهنة</th><th>الدور</th><th>التاريخ</th><th>إجراء</th></tr></thead><tbody><?php foreach($users as $user):?><tr><td><?=$user["id"]?></td><td><?=htmlspecialchars($user["full_name"])?></td><td><?=htmlspecialchars($user["phone"])?></td><td><?=htmlspecialchars($user["email"])?></td><td><?=htmlspecialchars($user["state"])?></td><td><?=htmlspecialchars($user["profession"])?></td><td><?=htmlspecialchars($user["role"])?></td><td><?=htmlspecialchars($user["created_at"])?></td><td><?php if($user["role"]!=="admin"):?><a class="delete" href="admin_delete.php?id=<?=$user["id"]?>" onclick="return confirm('هل أنت متأكد من حذف العضو؟')">حذف</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
